pub fn put4(b: &'static Bloblet<()>, at: Int, w: Int) -> () {
    bloblet_set_byte_x(b, at, modulo(w, int_lit(256)));
    bloblet_set_byte_x(b, _plus(at, int_lit(1)), modulo(quotient(w, int_lit(256)), int_lit(256)));
    bloblet_set_byte_x(b, _plus(at, int_lit(2)), modulo(quotient(w, int_lit(65536)), int_lit(256)));
    bloblet_set_byte_x(b, _plus(at, int_lit(3)), quotient(w, int_lit(16777216)))
}

/// Each item placed, at instruction `at` on; the first that did not
/// encode, as its place, or -1.
pub fn all_put_x(mut b: &'static Bloblet<()>, mut xs: List<&'static Item>, mut at: Int, mut ls: FlatArray<i64>) -> Int {
    loop {
        if null_p(xs) {
            return int_lit(-1);
        } else {
            let tagcase_ = car(xs);
            match *tagcase_ {
                Item::LabelHere(l) => {
                    xs = cdr(xs);
                    continue;
                }
                Item::AlignOdd(z) => {
                    if _eq(modulo(at, int_lit(2)), int_lit(0)) {
                        put4(b, _star(int_lit(4), at), arm_nop());
                        (xs, at) = (cdr(xs), _plus(at, int_lit(1)));
                        continue;
                    } else {
                        xs = cdr(xs);
                        continue;
                    }
                }
                _ => {
                    let x = tagcase_;
                    let w = encoded(x, at, ls);
                    if _lt(w, int_lit(0)) {
                        return at;
                    } else {
                        put4(b, _star(int_lit(4), at), w);
                        (xs, at) = (cdr(xs), _plus(at, int_lit(1)));
                        continue;
                    }
                }
            }
        }
    }
}

